          web = pkgs.runCommand "roast-web-tests" { nativeBuildInputs = [ pkgs.nodejs_22 ]; } ''
            cp -r ${./web} source
            chmod -R +w source
            cd source
            npm test
            ROAST_SKIP_WASM=1 npm run build
            test -f dist/index.html
            touch $out
          '';
        });

      devShells = forAllSystems (pkgs: {
