            pkgs.rustc pkgs.cargo pkgs.nodejs_22 pkgs.binaryen
          ];
          shellHook = ''
            echo "Roast Solver dev shell: pytest · cargo test --manifest-path rust-core/Cargo.toml · npm --prefix web run build"
          '';
        };
      });
    };
}

